import {
    type CommandExample,
    catchError,
    createHiddenDeprecatedTenantOption,
    extractErrorMessage,
    OutputFormatter,
    processContext,
    RESULTS,
} from "@uipath/common";
import { getFileSystem } from "@uipath/filesystem";
import { type Command, Option } from "commander";
import { readFileBinary } from "../utils/input";
import { fail, requireDestructiveConfirmation } from "../utils/output";
import { connectOrFail } from "../utils/sdk-client";

interface UploadOptions {
    tenant?: string;
    file?: string;
}

interface DownloadOptions {
    tenant?: string;
    destination?: string;
}

interface DeleteOptions {
    tenant?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
}

const FILES_UPLOAD_EXAMPLES: CommandExample[] = [
    {
        Description: "Upload a file attachment to a record field",
        Command:
            "uip df files upload a1b2c3d4-0000-0000-0000-000000000001 b2c3d4e5-0000-0000-0000-000000000001 invoice --file ./invoice.pdf",
        Output: {
            Code: "FileUploaded",
            Data: {
                EntityId: "a1b2c3d4-0000-0000-0000-000000000001",
                RecordId: "b2c3d4e5-0000-0000-0000-000000000001",
                FieldName: "invoice",
                FileName: "invoice.pdf",
            },
        },
    },
];

const FILES_DOWNLOAD_EXAMPLES: CommandExample[] = [
    {
        Description: "Download a file attachment from a record field",
        Command:
            "uip df files download a1b2c3d4-0000-0000-0000-000000000001 b2c3d4e5-0000-0000-0000-000000000001 invoice --destination ./invoice.pdf",
        Output: {
            Code: "FileDownloaded",
            Data: {
                EntityId: "a1b2c3d4-0000-0000-0000-000000000001",
                RecordId: "b2c3d4e5-0000-0000-0000-000000000001",
                FieldName: "invoice",
                OutputPath: "./invoice.pdf",
            },
        },
    },
];

const FILES_DELETE_EXAMPLES: CommandExample[] = [
    {
        Description: "Delete a file attachment from a record field",
        Command:
            "uip df files delete a1b2c3d4-0000-0000-0000-000000000001 b2c3d4e5-0000-0000-0000-000000000001 invoice",
        Output: {
            Code: "FileDeleted",
            Data: {
                EntityId: "a1b2c3d4-0000-0000-0000-000000000001",
                RecordId: "b2c3d4e5-0000-0000-0000-000000000001",
                FieldName: "invoice",
            },
        },
    },
];

export const registerFilesCommand = (program: Command) => {
    const files = program
        .command("files")
        .description("Manage file attachments on Data Fabric entity records");

    files
        .command("upload")
        .description("Upload a file to a field on an entity record")
        .argument("<entity-id>", "Entity ID")
        .argument("<record-id>", "Record ID")
        .argument("<field-name>", "Name of the file field (case-sensitive)")
        .addOption(
            createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>"),
        )
        .option("-f, --file <path>", "Path to the file to upload")
        .examples(FILES_UPLOAD_EXAMPLES)
        .trackedAction(
            processContext,
            async (
                entityId: string,
                recordId: string,
                fieldName: string,
                options: UploadOptions,
            ) => {
                if (!options.file) {
                    return fail(
                        "A file path is required",
                        "Provide a file path via --file.",
                    );
                }

                const sdk = await connectOrFail(options.tenant);
                if (!sdk) return;

                const [readError, fileContent] = await catchError(
                    readFileBinary(options.file),
                );

                if (readError) {
                    return fail("Error reading file", readError.message);
                }

                const fsInst = getFileSystem();
                const fileName = fsInst.path.basename(options.file) || "upload";

                const [uploadError] = await catchError(
                    sdk.entities.uploadAttachment(
                        entityId,
                        recordId,
                        fieldName,
                        new File(
                            [fileContent as Uint8Array<ArrayBuffer>],
                            fileName,
                        ),
                    ),
                );

                if (uploadError) {
                    return fail(
                        `Error uploading file to field '${fieldName}'`,
                        await extractErrorMessage(uploadError),
                    );
                }

                OutputFormatter.success({
                    Result: RESULTS.Success,
                    Code: "FileUploaded",
                    Data: {
                        EntityId: entityId,
                        RecordId: recordId,
                        FieldName: fieldName,
                        FileName: fileName,
                    },
                });
            },
        );

    files
        .command("download")
        .description("Download a file from a field on an entity record")
        .argument("<entity-id>", "Entity ID")
        .argument("<record-id>", "Record ID")
        .argument("<field-name>", "Name of the file field (case-sensitive)")
        .addOption(
            createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>"),
        )
        .option(
            "--destination <path>",
            "Output file path (defaults to <record-id>_<field-name>.bin)",
        )
        .examples(FILES_DOWNLOAD_EXAMPLES)
        .trackedAction(
            processContext,
            async (
                entityId: string,
                recordId: string,
                fieldName: string,
                options: DownloadOptions,
            ) => {
                const sdk = await connectOrFail(options.tenant);
                if (!sdk) return;

                const [downloadError, blob] = await catchError(
                    sdk.entities.downloadAttachment(
                        entityId,
                        recordId,
                        fieldName,
                    ),
                );

                if (downloadError) {
                    return fail(
                        `Error downloading file from field '${fieldName}'`,
                        await extractErrorMessage(downloadError),
                    );
                }

                const outputPath =
                    options.destination ?? `${recordId}_${fieldName}.bin`;

                const [bufferError, arrayBuffer] = await catchError(
                    (blob as Blob).arrayBuffer(),
                );

                if (bufferError) {
                    return fail(
                        "Error reading downloaded file content",
                        bufferError.message,
                    );
                }

                const [writeError] = await catchError(
                    writeFileBinary(outputPath, new Uint8Array(arrayBuffer)),
                );

                if (writeError) {
                    return fail(
                        "Error writing downloaded file",
                        writeError.message,
                    );
                }

                OutputFormatter.success({
                    Result: RESULTS.Success,
                    Code: "FileDownloaded",
                    Data: {
                        EntityId: entityId,
                        RecordId: recordId,
                        FieldName: fieldName,
                        OutputPath: outputPath,
                    },
                });
            },
        );

    files
        .command("delete")
        .description("Delete a file from a field on an entity record")
        .argument("<entity-id>", "Entity ID")
        .argument("<record-id>", "Record ID")
        .argument("<field-name>", "Name of the file field (case-sensitive)")
        .addOption(
            createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>"),
        )
        .option("-y, --yes", "Acknowledge this is an irreversible operation")
        .addOption(
            new Option("--confirm", "Deprecated alias for --yes").hideHelp(),
        )
        .option(
            "--reason <reason>",
            "Reason for the deletion — echoed back in the response so the caller can log it",
        )
        .examples(FILES_DELETE_EXAMPLES)
        .trackedAction(
            processContext,
            async (
                entityId: string,
                recordId: string,
                fieldName: string,
                options: DeleteOptions,
            ) => {
                const reason = requireDestructiveConfirmation(
                    options,
                    `delete the file in field '${fieldName}'`,
                    'Pass --reason "<text>" to record why the file is being deleted.',
                );
                if (reason === null) return;

                const sdk = await connectOrFail(options.tenant);
                if (!sdk) return;

                const [deleteError] = await catchError(
                    sdk.entities.deleteAttachment(
                        entityId,
                        recordId,
                        fieldName,
                    ),
                );

                if (deleteError) {
                    return fail(
                        `Error deleting file from field '${fieldName}'`,
                        await extractErrorMessage(deleteError),
                    );
                }

                OutputFormatter.success({
                    Result: RESULTS.Success,
                    Code: "FileDeleted",
                    Data: {
                        EntityId: entityId,
                        RecordId: recordId,
                        FieldName: fieldName,
                        Reason: reason,
                    },
                });
            },
        );
};

async function writeFileBinary(
    filePath: string,
    data: Uint8Array,
): Promise<void> {
    const fs = getFileSystem();
    await fs.writeFile(filePath, data);
}
